import{_ as r,o as a,c as o,a2 as t}from"./chunks/framework.BTLSZHNB.js";const u=JSON.parse('{"title":"ModuleWorker — takoform_module_worker","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/module-worker.md","filePath":"proposals/edge/module-worker.md"}'),i={name:"proposals/edge/module-worker.md"};function n(s,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="moduleworker-—-takoform-module-worker" tabindex="-1">ModuleWorker — <code>takoform_module_worker</code> <a class="header-anchor" href="#moduleworker-—-takoform-module-worker" aria-label="Permalink to &quot;ModuleWorker — `takoform_module_worker`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>An application team runs an HTTP/event application as one ES Module Worker on a proven edge platform. Consumers address the worker by its logical identity: deployments, domains, triggers, consumers, and service bindings all point at this resource, never at a specific build.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>identity</code>. The Form carries no desired fields: everything that can change — code, configuration, bindings, traffic — lives on revision and deployment resources around it.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p>The identity fixes the ES Module Worker ABI: handlers are functions exported from an ES module (<code>fetch</code>, <code>scheduled</code>, <code>queue</code>, <code>tail</code>), invoked with typed events and an environment object carrying the revision&#39;s declared bindings. An instance is stateless between events; durable state lives behind bindings.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Every consumer of the family programs against exactly this ABI. Splitting the identity from the ABI would let two hosts attach the same deployments to observably different runtimes.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>A WASI function, an OCI container service, or an isolate model with a different handler contract each preserve a different shape and are separate Forms in other families.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None on the identity; <code>worker.service</code> is provided by <a href="./worker-version.html">WorkerVersion</a>, whose snapshot actually answers invocations.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None. Capability bindings belong to revision resources (decision 0010).</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Deleting the identity while versions, deployments, or attachments reference it must fail with <code>dependency_in_use</code>. Delete/recreate mints a new UID (decision 0011); stale references never rebind silently.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The module-worker execution model of a proven edge platform, retained here without its vendor, account, or commercial surface. The retained v1alpha2 <code>EdgeWorker</code> candidate is prior art that this family supersedes for new design work.</p>',19)])])}const p=r(i,[["render",n]]);export{u as __pageData,p as default};
